395	  if (remaining > 0) return;
396	  const any = await db.coldSend.count({ where: { campaignId } });
397	  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
398	  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
