401	/**
402	 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
403	 * keeps everything below inert until a human enables sending on prod.
404	 */
405	export async function coldEmailSendSweep(): Promise<void> {
406	  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
407	  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;
408	
409	  let campaigns: CampaignForSend[];
410	  try {
411	    campaigns = await db.coldCampaign.findMany({
412	      where: { status: "SENDING" },
413	      select: {
414	        id: true,
415	        brandId: true,
416	        listId: true,
417	        launchedAt: true,
418	        sendWindowStart: true,
419	        sendWindowEnd: true,
420	        timezone: true,
421	      },
422	    });
423	  } catch {
424	    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
425	    return;
426	  }
427	  if (campaigns.length === 0) return;
428	
429	  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
430	  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
431	  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
432	  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
433	  const now = new Date();
434	
435	  let transport: MailTransport;
436	  try {
437	    transport = await getTransport("nxeon-smtp");
438	  } catch (err) {
439	    await logEvent("error", "coldemail.transport.init", { message: String(err) });
440	    return;
441	  }
442	
443	  let budget = MAX_SENDS_PER_SWEEP;
444	  for (const campaign of campaigns) {
445	    if (budget <= 0) break;
446	
447	    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
448	    if (!brand) continue;
449	
450	    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
451	    const eligibility = evaluateSendEligibility(brand, protectedSet);
452	    if (!eligibility.eligible) {
453	      await logEvent("warn", "coldemail.send.brand_blocked", {
454	        campaignId: campaign.id,
455	        brandId: brand.id,
456	        reasons: eligibility.reasons,
457	      });
458	      continue;
459	    }
460	
461	    const identity: SendIdentity = {
462	      id: brand.id,
463	      name: brand.name,
464	      fromName: brand.fromName,
465	      fromEmail: brand.fromEmail,
466	      replyTo: brand.replyTo,
467	      sendingDomain: brand.sendingDomain,
468	      physicalPostalAddress: brand.physicalPostalAddress,
469	    };
470	
471	    try {
472	      await scheduleCampaignSends(campaign);
473	      const sent = await processDueSends(campaign, identity, {
474	        now,
475	        transport,
476	        ceiling,
477	        warmupEnabled,
478	        footerDisclosure,
479	        budget,
480	      });
481	      budget -= sent;
482	      await maybeCompleteCampaign(campaign.id);
483	    } catch (err) {
484	      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
485	    }
486	  }
487	}
