1	// Cold Email Engine — threaded reply send from an inbox's own SMTP (Phase 1).
2	//
3	// This is the "1:1 operator reply" path. It is NORMAL email to an existing
4	// conversation (someone who already replied to us), so it is allowed even while
5	// the bulk kill-switch `cold_email_sending_enabled` is OFF — it never touches the
6	// bulk queue. It sends from the conversation's inbox using THAT inbox's own SMTP
7	// credentials (decrypted from smtpPassEnc), sets the RFC threading headers so the
8	// message stays in the thread, logs an OUTBOUND Message, and marks the
9	// conversation read.
10	//
11	// INERT without creds: an inbox with a blank smtpHost cannot send — the caller
12	// gets a clear error instead of a connection attempt.
13	
14	import { db } from "@/lib/db";
15	import { decryptSecret } from "@/lib/crypto-box";
16	import { NxeonSmtpTransport, markdownToHtml, type RenderedMessage } from "@/lib/coldemail/sender";
17	import { wrapEmail } from "@/lib/email-render";
18	import { buildThreadHeaders, replySubject, normalizeMessageId } from "@/lib/coldemail/threading";
19	import { logEvent } from "@/lib/log";
20	
21	/** Mint a fresh Message-ID for an outbound reply so later replies thread to it. */
22	function newMessageId(fromAddr: string): string {
23	  const domain = (fromAddr.split("@")[1] || "nxeon.cloud").trim() || "nxeon.cloud";
24	  const rand = `${Date.now().toString(36)}.${Math.random().toString(36).slice(2, 12)}`;
25	  return `<${rand}@${domain}>`;
26	}
27	
28	export type SendReplyResult = { ok: true; messageId: string } | { ok: false; error: string };
29	
30	/**
31	 * Send a threaded reply within a conversation from its inbox's SMTP, and log the
32	 * outbound Message. Threads onto the most recent message in the conversation.
33	 */
34	export async function sendConversationReply(opts: {
35	  conversationId: string;
36	  bodyMarkdown: string;
37	  subjectOverride?: string;
38	}): Promise<SendReplyResult> {
39	  const body = (opts.bodyMarkdown ?? "").trim();
40	  if (!body) return { ok: false, error: "Write a message before sending." };
41	
42	  const conversation = await db.conversation.findUnique({
43	    where: { id: opts.conversationId },
44	    include: {
45	      contact: { select: { email: true } },
46	      inbox: {
47	        select: {
48	          email: true,
49	          smtpHost: true,
50	          smtpPort: true,
51	          smtpUser: true,
52	          smtpPassEnc: true,
53	          smtpTls: true,
54	        },
55	      },
56	      // Newest message = the one we thread our reply onto.
57	      messages: { orderBy: { createdAt: "desc" }, take: 1 },
58	    },
59	  });
60	  if (!conversation) return { ok: false, error: "Conversation not found." };
61	
62	  const inbox = conversation.inbox;
63	  if (!inbox.smtpHost || !inbox.smtpUser) {
64	    return { ok: false, error: "This inbox has no SMTP credentials configured — set them on Domains & inboxes first." };
65	  }
66	  const pass = decryptSecret(inbox.smtpPassEnc) ?? "";
67	
68	  const to = conversation.contact.email;
69	  const parent = conversation.messages[0] ?? null;
70	  const subject = (opts.subjectOverride ?? "").trim() || replySubject(conversation.subject);
71	  const thread = parent ? buildThreadHeaders(parent.messageId, parent.references) : {};
72	  const messageId = newMessageId(inbox.email);
73	
74	  const bodyHtml = wrapEmail(markdownToHtml(body), { preheader: subject });
75	  const headers: Record<string, string> = {
76	    "Message-ID": messageId,
77	    "X-Nxeon-Cold-Email": "reply",
78	    ...thread,
79	  };
80	
81	  const msg: RenderedMessage = {
82	    from: inbox.email,
83	    to,
84	    subject,
85	    html: bodyHtml,
86	    text: body,
87	    headers,
88	  };
89	
90	  try {
91	    const transport = new NxeonSmtpTransport({
92	      host: inbox.smtpHost,
93	      port: inbox.smtpPort,
94	      user: inbox.smtpUser,
95	      pass,
96	      secure: inbox.smtpTls,
97	    });
98	    await transport.send(msg);
99	  } catch (err) {
100	    const error = String((err as Error)?.message ?? err).slice(0, 300);
101	    await logEvent("error", "coldemail.reply.send", { conversationId: opts.conversationId, error });
102	    return { ok: false, error: `Send failed: ${error}` };
103	  }
104	
105	  const now = new Date();
106	  await db.message.create({
107	    data: {
108	      conversationId: conversation.id,
109	      direction: "OUTBOUND",
110	      fromAddr: inbox.email,
111	      toAddr: to,
112	      subject,
113	      bodyText: body,
114	      bodyHtml,
115	      messageId,
116	      inReplyTo: thread["In-Reply-To"] ?? "",
117	      references: thread.References ?? "",
118	      sentAt: now,
119	    },
120	  });
121	
122	  await db.conversation.update({
123	    where: { id: conversation.id },
124	    // An operator reply clears the unread flag and, if the thread was still just
125	    // OPEN, moves it to REPLIED. A classified status (INTERESTED, etc.) is preserved.
126	    data: {
127	      unread: false,
128	      lastMessageAt: now,
129	      status: conversation.status === "OPEN" ? "REPLIED" : conversation.status,
130	    },
131	  });
132	
133	  await logEvent("info", "coldemail.reply.sent", { conversationId: conversation.id, messageId: normalizeMessageId(messageId) });
134	  return { ok: true, messageId };
135	}
