445	// ---------------------------------------------------------------------------
446	
447	/**
448	 * The compliance footer that every message must carry: the sender's physical
449	 * postal address (CAN-SPAM) plus a one-click unsubscribe line (RFC 8058 /
450	 * Gmail-Yahoo). Plain text — the template layer wraps it for HTML.
451	 */
452	export function complianceFooter(brand: BrandLike, unsubscribeUrl: string): string {
453	  const address = (brand.physicalPostalAddress ?? "").trim() || "[physical postal address not set]";
454	  return [
455	    "You are receiving this message as a business contact.",
456	    `Our postal address: ${address}`,
457	    `To stop receiving these emails, unsubscribe here: ${unsubscribeUrl}`,
458	  ].join("\n");
459	}
