14	 *
15	 * PROTECTED by a shared secret. Set `COLDEMAIL_FEEDBACK_SECRET` and send it as
16	 * `Authorization: Bearer <secret>` (or `?secret=`). With no secret configured the
17	 * endpoint refuses everything — it never processes unauthenticated feedback.
18	 *
19	 * Body: { "email": "...", "kind": "BOUNCE" | "COMPLAINT", "note"?: "..." }
20	 */
21	export async function POST(req: Request) {
22	  const secret = process.env.COLDEMAIL_FEEDBACK_SECRET;
23	  if (!secret) {
24	    return NextResponse.json({ error: "Feedback endpoint disabled — no secret configured." }, { status: 503 });
25	  }
26	  const auth = req.headers.get("authorization") ?? "";
27	  const bearer = auth.startsWith("Bearer ") ? auth.slice(7) : "";
28	  const qs = new URL(req.url).searchParams.get("secret") ?? "";
29	  if (bearer !== secret && qs !== secret) {
30	    return NextResponse.json({ error: "Unauthorized." }, { status: 401 });
31	  }
32	
33	  let body: { email?: string; kind?: string; note?: string };
34	  try {
35	    body = await req.json();
36	  } catch {
37	    return NextResponse.json({ error: "Invalid JSON." }, { status: 400 });
38	  }
39	
40	  const email = String(body.email ?? "").trim();
41	  const kindRaw = String(body.kind ?? "").toUpperCase();
42	  if (!email) return NextResponse.json({ error: "Missing email." }, { status: 400 });
43	  if (kindRaw !== "BOUNCE" && kindRaw !== "COMPLAINT") {
44	    return NextResponse.json({ error: "kind must be BOUNCE or COMPLAINT." }, { status: 400 });
45	  }
46	
47	  const result = await recordFeedback(email, kindRaw as FeedbackKind, { note: body.note });
48	  return NextResponse.json(result, { status: result.ok ? 200 : 422 });
